{
  "framework": "solid",
  "component": "dialog",
  "props": {
    "Backdrop": {
      "props": {
        "asChild": {
          "type": "(props: ParentProps<'div'>) => Element",
          "isRequired": false,
          "description": "Use the provided child element as the default rendered element, combining their props and behavior."
        }
      }
    },
    "CloseTrigger": {
      "props": {
        "asChild": {
          "type": "(props: ParentProps<'button'>) => Element",
          "isRequired": false,
          "description": "Use the provided child element as the default rendered element, combining their props and behavior."
        }
      }
    },
    "Content": {
      "props": {
        "asChild": {
          "type": "(props: ParentProps<'div'>) => Element",
          "isRequired": false,
          "description": "Use the provided child element as the default rendered element, combining their props and behavior."
        }
      }
    },
    "Description": {
      "props": {
        "asChild": {
          "type": "(props: ParentProps<'div'>) => Element",
          "isRequired": false,
          "description": "Use the provided child element as the default rendered element, combining their props and behavior."
        }
      }
    },
    "Positioner": {
      "props": {
        "asChild": {
          "type": "(props: ParentProps<'div'>) => Element",
          "isRequired": false,
          "description": "Use the provided child element as the default rendered element, combining their props and behavior."
        }
      }
    },
    "Root": {
      "props": {
        "aria-label": {
          "type": "string",
          "isRequired": false,
          "description": "Human readable label for the dialog, in event the dialog title is not rendered"
        },
        "closeOnEscape": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "true",
          "description": "Whether to close the dialog when the escape key is pressed"
        },
        "closeOnInteractOutside": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "true",
          "description": "Whether to close the dialog when the outside is clicked"
        },
        "defaultOpen": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "false",
          "description": "The initial open state of the dialog when rendered.\nUse when you don't need to control the open state of the dialog."
        },
        "defaultTriggerValue": {
          "type": "string",
          "isRequired": false,
          "description": "The initial active trigger value when rendered.\nUse when you don't need to control the active trigger value."
        },
        "finalFocusEl": {
          "type": "() => MaybeElement",
          "isRequired": false,
          "description": "Element to receive focus when the dialog is closed"
        },
        "id": {
          "type": "string",
          "isRequired": false,
          "description": "The unique identifier of the machine."
        },
        "ids": {
          "type": "Partial<{\n  trigger: string | ((value?: string | undefined) => string)\n  positioner: string\n  backdrop: string\n  content: string\n  closeTrigger: string\n  title: string\n  description: string\n}>",
          "isRequired": false,
          "description": "The ids of the elements in the dialog. Useful for composition."
        },
        "immediate": {
          "type": "boolean",
          "isRequired": false,
          "description": "Whether to synchronize the present change immediately or defer it to the next frame"
        },
        "initialFocusEl": {
          "type": "() => MaybeElement",
          "isRequired": false,
          "description": "Element to receive focus when the dialog is opened"
        },
        "lazyMount": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "false",
          "description": "Whether to enable lazy mounting"
        },
        "modal": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "true",
          "description": "Whether to prevent pointer interaction outside the element and hide all content below it"
        },
        "onEscapeKeyDown": {
          "type": "(event: KeyboardEvent) => void",
          "isRequired": false,
          "description": "Function called when the escape key is pressed"
        },
        "onExitComplete": {
          "type": "VoidFunction",
          "isRequired": false,
          "description": "Function called when the animation ends in the closed state"
        },
        "onFocusOutside": {
          "type": "(event: FocusOutsideEvent) => void",
          "isRequired": false,
          "description": "Function called when the focus is moved outside the component"
        },
        "onInteractOutside": {
          "type": "(event: InteractOutsideEvent) => void",
          "isRequired": false,
          "description": "Function called when an interaction happens outside the component"
        },
        "onOpenChange": {
          "type": "(details: OpenChangeDetails) => void",
          "isRequired": false,
          "description": "Function to call when the dialog's open state changes"
        },
        "onPointerDownOutside": {
          "type": "(event: PointerDownOutsideEvent) => void",
          "isRequired": false,
          "description": "Function called when the pointer is pressed down outside the component"
        },
        "onRequestDismiss": {
          "type": "(event: LayerDismissEvent) => void",
          "isRequired": false,
          "description": "Function called when this layer is closed due to a parent layer being closed"
        },
        "onTriggerValueChange": {
          "type": "(details: TriggerValueChangeDetails) => void",
          "isRequired": false,
          "description": "Function to call when the active trigger changes"
        },
        "open": {
          "type": "boolean",
          "isRequired": false,
          "description": "The controlled open state of the dialog"
        },
        "persistentElements": {
          "type": "(() => Element | null)[]",
          "isRequired": false,
          "description": "Returns the persistent elements that:\n- should not have pointer-events disabled\n- should not trigger the dismiss event"
        },
        "present": {
          "type": "boolean",
          "isRequired": false,
          "description": "Whether the node is present (controlled by the user)"
        },
        "preventScroll": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "true",
          "description": "Whether to prevent scrolling behind the dialog when it's opened"
        },
        "restoreFocus": {
          "type": "boolean",
          "isRequired": false,
          "description": "Whether to restore focus to the element that had focus before the dialog was opened"
        },
        "role": {
          "type": "'dialog' | 'alertdialog'",
          "isRequired": false,
          "defaultValue": "\"dialog\"",
          "description": "The dialog's role"
        },
        "skipAnimationOnMount": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "false",
          "description": "Whether to allow the initial presence animation."
        },
        "trapFocus": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "true",
          "description": "Whether to trap focus inside the dialog when it's opened"
        },
        "triggerValue": {
          "type": "string",
          "isRequired": false,
          "description": "The controlled active trigger value"
        },
        "unmountOnExit": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "false",
          "description": "Whether to unmount on exit."
        }
      }
    },
    "RootProvider": {
      "props": {
        "value": {
          "type": "UseDialogReturn",
          "isRequired": true
        },
        "immediate": {
          "type": "boolean",
          "isRequired": false,
          "description": "Whether to synchronize the present change immediately or defer it to the next frame"
        },
        "lazyMount": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "false",
          "description": "Whether to enable lazy mounting"
        },
        "onExitComplete": {
          "type": "VoidFunction",
          "isRequired": false,
          "description": "Function called when the animation ends in the closed state"
        },
        "present": {
          "type": "boolean",
          "isRequired": false,
          "description": "Whether the node is present (controlled by the user)"
        },
        "skipAnimationOnMount": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "false",
          "description": "Whether to allow the initial presence animation."
        },
        "unmountOnExit": {
          "type": "boolean",
          "isRequired": false,
          "defaultValue": "false",
          "description": "Whether to unmount on exit."
        }
      }
    },
    "Title": {
      "props": {
        "asChild": {
          "type": "(props: ParentProps<'h2'>) => Element",
          "isRequired": false,
          "description": "Use the provided child element as the default rendered element, combining their props and behavior."
        }
      }
    },
    "Trigger": {
      "props": {
        "asChild": {
          "type": "(props: ParentProps<'button'>) => Element",
          "isRequired": false,
          "description": "Use the provided child element as the default rendered element, combining their props and behavior."
        },
        "value": {
          "type": "string",
          "isRequired": false,
          "description": "The value that identifies this specific trigger"
        }
      }
    }
  }
}
